<body>
<div class="app">
  <h1>Todos</h1>
  <div class="input-row">
    <input type="text" id="todoInput" placeholder="What needs to be done?" autofocus>
    <button id="addBtn">Add</button>
  </div>
  <div class="filters">
    <button class="active" data-filter="all">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="completed">Completed</button>
  </div>
  <ul class="todo-list" id="todoList"></ul>
  <div class="count" id="count"></div>
</div>

<script>
(function() {
  const STORAGE_KEY = 'todo_app_todos';
  const FILTER_KEY = 'todo_app_filter';

  let todos = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  let currentFilter = localStorage.getItem(FILTER_KEY) || 'all';

  const input = document.getElementById('todoInput');
  const addBtn = document.getElementById('addBtn');
  const list = document.getElementById('todoList');
  const countEl = document.getElementById('count');
  const filterBtns = document.querySelectorAll('.filters button');

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    localStorage.setItem(FILTER_KEY, currentFilter);
  }

  function addTodo() {
    const text = input.value.trim();
    if (!text) return;
    todos.push({ id: Date.now(), text, completed: false });
    input.value = '';
    save();
    render();
  }

  function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      save();
      render();
    }
  }

  function deleteTodo(id) {
    todos = todos.filter(t => t.id !== id);
    save();
    render();
  }

  function getFiltered() {
    if (currentFilter === 'active') return todos.filter(t => !t.completed);
    if (currentFilter === 'completed') return todos.filter(t => t.completed);
    return todos;
  }

  function render() {
    const filtered = getFiltered();
    if (filtered.length === 0) {
      list.innerHTML = '<li class="empty">' +
        (todos.length === 0 ? 'No todos yet. Add one above!' : 'No matching todos.') +
        '</li>';
    } else {
      list.innerHTML = filtered.map(t =>
        '<li class="todo-item">' +
          '<input type="checkbox" ' + (t.completed ? 'checked' : '') + ' data-id="' + t.id + '">' +
          '<span class="text' + (t.completed ? ' completed' : '') + '">' + escapeHtml(t.text) + '</span>' +
          '<button class="delete" data-id="' + t.id + '">&times;</button>' +
        '</li>'
      ).join('');
    }
    const remaining = todos.filter(t => !t.completed).length;
    countEl.textContent = remaining + ' item' + (remaining !== 1 ? 's' : '') + ' left';
  }

  function escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  list.addEventListener('click', function(e) {
    if (e.target.classList.contains('delete')) {
      deleteTodo(Number(e.target.dataset.id));
    }
  });

  list.addEventListener('change', function(e) {
    if (e.target.type === 'checkbox') {
      toggleTodo(Number(e.target.dataset.id));
    }
  });

  filterBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;
      save();
      render();
    });
  });

  addBtn.addEventListener('click', addTodo);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') addTodo();
  });

  render();
})();
</script>
</body>
</html>
